import json
from fractions import Fraction as F

# F(x,y,u,p,q)=pq-u. Charpit's equations are
# x'=q, y'=p, u'=2pq, p'=p, q'=q.
# On the initial curve, du/dtau=q=2*tau and pq=tau^2.
# Thus, for tau != 0, p=tau/2; the continuous extension gives p=0
# at tau=0. Write p0=a*tau, q0=b*tau.
b = F(2)
a = F(1) / b
assert a * b == 1

# Laurent polynomials in t=e^s, normalized by tau for x,y
# and by tau^2 for u.
derived = (
    {1: b, 0: -b},
    {1: a, 0: 1 - a},
    {2: a * b, 0: 1 - a * b},
)

options = [
    ({1: F(3), 0: F(-3)},
     {-1: F(1, 2), 0: F(1, 2)},
     {-2: F(1)}),
    ({1: F(2), 0: F(-2)},
     {2: F(2), 0: F(-1)},
     {0: F(1, 2), -2: F(1, 2)}),
    ({1: F(2), 0: F(-2)},
     {1: F(1, 2), 0: F(1, 2)},
     {2: F(1)}),
    ({-1: F(1), 0: F(-1)},
     {-1: F(-2), 0: F(3)},
     {-2: F(2), 0: F(-1)}),
]

def clean(poly):
    return {k: v for k, v in poly.items() if v}

def evaluate_at_one(poly):
    return sum(poly.values(), F(0))

def derivative_s(poly):
    return clean({k: k * v for k, v in poly.items()})

derived = tuple(clean(poly) for poly in derived)

# Independently verify the integrated equations and initial data.
assert tuple(map(evaluate_at_one, derived)) == (0, 1, 1)
assert derivative_s(derived[0]) == {1: b}
assert derivative_s(derived[1]) == {1: a}
assert derivative_s(derived[2]) == {2: 2 * a * b}

matches = [
    i for i, option in enumerate(options, 1)
    if tuple(clean(poly) for poly in option) == derived
]

def exact_terms(poly):
    return {str(k): str(v) for k, v in sorted(poly.items())}

result = {
    "final_answer": (
        "Option " + str(matches[0]) if len(matches) == 1 else "UNSUPPORTED"
    ),
    "evidence": {
        "Charpit": ["x'=q", "y'=p", "u'=2pq", "p'=p", "q'=q"],
        "initial_p_over_tau": str(a),
        "initial_q_over_tau": str(b),
        "t": "e^s",
        "Laurent_coefficients": {
            name: exact_terms(poly)
            for name, poly in zip(("x/tau", "y/tau", "u/tau^2"), derived)
        },
        "matching_options": matches,
    },
}
print(json.dumps(result, separators=(",", ":")))
