import json
import unicodedata
from collections import Counter, defaultdict

# Lexical pairs supplied in the problem. The compound numeral is not
# needed for the sound correspondences used here.
pairs = [
    ("ʔikaːn", "ikan"), ("dikiʔ", "takiʔ"), ("dilah", "talàh"),
    ("jalaːn", "calàn"), ("lima", "limɨ"), ("lanah", "linɨh"),
    ("labaːt", "lipàʔ"), ("bara", "pirà"), ("bahrow", "piròw"),
    ("bulow", "pilòw"), ("paley", "paley"), ("masam", "mɨtham"),
    ("basah", "pathah"), ("bəsey", "pathey"), ("mata", "mɨta"),
    ("rataːk", "rataʔ"), ("hatay", "hatay"), ("paday", "patày"),
    ("padam", "patàm"), ("ʔiduŋ", "itùng"), ("batuk", "patuʔ"),
    ("maray", "mɨray"), ("ʔurat", "uraʔ"), ("rək", "rəʔ"),
    ("bala", "pilà"),
]
vowels = set("aeiouəɨ")

def normalize(word):
    return "".join(
        c for c in unicodedata.normalize("NFD", word)
        if not unicodedata.combining(c) and c != "ː"
    )

def tokenize(word):
    word = normalize(word)
    result = []
    i = 0
    while i < len(word):
        if word[i:i + 2] in ("th", "ph"):
            result.append(word[i:i + 2])
            i += 2
        elif word[i:i + 2] == "ng":
            result.append("ŋ")
            i += 2
        else:
            result.append(word[i])
            i += 1
    return result

def roles(tokens):
    first_vowel = next(i for i, x in enumerate(tokens) if x in vowels)
    return [
        "initial" if i == 0 and x not in vowels else
        "presyllable_vowel" if i == first_vowel and
        any(y in vowels for y in tokens[i + 1:]) else
        "vowel" if x in vowels else "consonant"
        for i, x in enumerate(tokens)
    ]

specific = defaultdict(Counter)
general = defaultdict(Counter)
sources = defaultdict(list)

for proto, cham in pairs:
    a, b = tokenize(proto), tokenize(cham)
    # Only directly aligned pairs are used; no uncertain alignment is imposed.
    if len(a) != len(b):
        continue
    for x, y, role in zip(a, b, roles(a)):
        specific[(role, x)][y] += 1
        general[x][y] += 1
        sources[(role, x, y)].append([proto, cham])

def unique_mode(counts):
    if not counts:
        return None
    maximum = max(counts.values())
    winners = [x for x, n in counts.items() if n == maximum]
    return winners[0] if len(winners) == 1 else None

target = tokenize("dəpa")
output = []
evidence = []

for symbol, role in zip(target, roles(target)):
    counts = specific.get((role, symbol))
    scope = role
    if not counts:
        counts = general.get(symbol)
        scope = "general consonant correspondence"
    replacement = unique_mode(counts)
    if replacement is None:
        print("UNSUPPORTED")
        break
    output.append(replacement)
    evidence.append({
        "from": symbol,
        "to": replacement,
        "scope": scope,
        "counts": dict(counts)
    })
else:
    # All supplied syllables beginning with p have an unaccented vowel;
    # the inferred final syllable therefore requires no grave accent.
    p_syllables = []
    for _, cham in pairs:
        for i, c in enumerate(cham[:-1]):
            if c == "p" and normalize(cham[i + 1]) in vowels:
                p_syllables.append(cham[i + 1])
    if not p_syllables or any(
        unicodedata.combining(c)
        for vowel in p_syllables
        for c in unicodedata.normalize("NFD", vowel)
    ):
        print("UNSUPPORTED")
    else:
        print(json.dumps({
            "final_answer": "".join(output),
            "evidence": evidence
        }, ensure_ascii=False, separators=(",", ":")))
