import json
import math

number = 33146799
remaining = number
factors = []
divisor = 2

while divisor * divisor <= remaining:
    while remaining % divisor == 0:
        factors.append(divisor)
        remaining //= divisor
    divisor = 3 if divisor == 2 else divisor + 2

if remaining > 1:
    factors.append(remaining)

primes = sorted(set(factors))
product = math.prod(factors)

if product != number:
    print("UNSUPPORTED")
else:
    print(json.dumps({
        "final_answer": ", ".join(map(str, primes)),
        "evidence": {
            "number": number,
            "prime_factorization": [
                [prime, factors.count(prime)] for prime in primes
            ],
            "product": product
        }
    }, separators=(",", ":")))
