from itertools import permutations

# Adjective classes. Adjectives in the same semantic class share an order.
classes = {
    "origin": "ethiopian turkish japanese bangladeshi iranian".split(),
    "shape": "pyramidal rectangular circular prismlike triangular".split(),
    "size": "massive midsize medium-size small enormous normal-size huge large".split(),
    "purpose": "hiking typing driving whittling eating drinking".split(),
    "material": "wool plastic glass cardboard paper steel leather wood".split(),
    "age": "old-fashioned brand-new ancient old new".split(),
    "color": "green yellow indigo gray pink violet brown maroon".split(),
    "opinion": "silly repulsive lovely ridiculous terrible good".split(),
}
category = {
    adjective: name
    for name, adjectives in classes.items()
    for adjective in adjectives
}

# Given examples establishing every distinct class-order constraint.
# The remaining multi-adjective examples repeat these constraints.
evidence = {
    4: "paper ancient",
    11: "bangladeshi spherical",
    17: "maroon good",
    19: "medium-size hiking",
    40: "triangular large new",
    175: "iranian eating glass",
}
category["spherical"] = "shape"

constraints = set()
for phrase in evidence.values():
    sequence = [category[word] for word in phrase.split()]
    constraints.update(
        (sequence[i], sequence[j])
        for i in range(len(sequence))
        for j in range(i + 1, len(sequence))
    )

options = {
    "A": "massive hiking wool old-fashioned green silly",
    "B": "repulsive midsize typing plastic brand-new pyramidal ethiopian",
    "C": "ethiopian rectangular medium-size driving glass ancient repulsive",
    "D": "turkish circular massive whittling cardboard old yellow lovely",
    "E": "japanese prismlike small eating paper old-fashioned indigo",
    "F": "massive typing paper old-fashioned ridiculous gray",
    "G": "pyramidal medium-size drinking steel new pink ridiculous",
    "H": "violet lovely enormous hiking leather new triangular",
    "I": "terrible brown normal-size typing glass old triangular japanese",
    "J": "bangladeshi prismlike huge drinking wood ancient",
}
option_classes = {
    letter: [category[word] for word in phrase.split()]
    for letter, phrase in options.items()
}

# Exhaustively consider every total class order consistent with the evidence.
results = []
for ordering in permutations(classes):
