    # At an interior maximum, Lagrange multiplier equations imply either
    # two variables coincide or all three coincide. The latter violates q=14.
    # With repeated variable t, the constraints give 3*t^2 - 18*t + 14=0.
    roots = [(F(3), F(-1, 3)), (F(3), F(1, 3))]
    candidates = []
    rejected = []
    for t in roots:
        s = sub(scalar(9), mul(scalar(2), t))
        if sign(t) > 0 and sign(s) > 0:
            candidates.append((t, t, s))
        else:
            rejected.append({"repeated": fmt(t), "remaining": fmt(s)})

    assert len(candidates) == 1
    values = candidates[0]
    x, y, z = values
    total = add(add(x, y), z)
    q = add(add(mul(x, y), mul(y, z)), mul(z, x))
    r = mul(mul(x, y), z)
    assert total == scalar(9) and q == scalar(14) and sign(r) > 0

    # For every feasible triple:
    # S = (1876 - 36*r)/(126 - r).
    # Its derivative is -2660/(126-r)^2, hence maximizing r minimizes S.
    # The denominator equals (x+y)(x+z)(y+z), so it is positive.
    derivative_numerator = -36 * 126 + 1876
    assert derivative_numerator < 0
    answer = objective(values)
    reduced = div(
        sub(scalar(1876), mul(scalar(36), r)),
        sub(scalar(126), r)
    )
    assert answer == reduced

    print(json.dumps({
        "final_answer": fmt(answer),
        "evidence": {
            "minimizing_triple_up_to_permutation": [fmt(v) for v in values],
            "sum": fmt(total),
            "pairwise_product_sum": fmt(q),
            "maximum_xyz": fmt(r),
            "objective_formula": "(1876-36*r)/(126-r), r=xyz",
            "derivative_numerator": derivative_numerator,
            "excluded_stationary_candidate": rejected,
            "global_certificate": (
                "The objective decreases with xyz. Boundary products are zero; "
                "every interior product maximum has two equal variables. "
                "The quadratic for that repeated variable has exactly one "
                "positive feasible triple."
            )
        }
    }, separators=(",", ":")))
except (ArithmeticError, AssertionError):
    print(json.dumps({"final_answer": "UNSUPPORTED", "evidence": "Exact checks failed."}))
